import Foundation
import MusicCore
import Notation
import ScoreImport

/// A song in the library, as listed without opening its file.
public struct SongEntry: Identifiable, Codable, Hashable, Sendable {
    public enum Format: String, Codable, Sendable {
        case midi, musicXML
        /// An exercise generated by the app; it has no file.
        case drill
    }

    public let id: UUID
    public var title: String
    public let addedAt: Date
    public let format: Format
    /// Name of the imported file inside the song's folder.
    public let fileName: String
    public let noteCount: Int
    public let lowestPitch: Int
    public let highestPitch: Int
    /// Length at the song's own tempo, to the end of the last bar.
    public let durationSeconds: Double

    public init(
        id: UUID, title: String, addedAt: Date, format: Format, fileName: String,
        noteCount: Int, lowestPitch: Int, highestPitch: Int, durationSeconds: Double
    ) {
        self.id = id
        self.title = title
        self.addedAt = addedAt
        self.format = format
        self.fileName = fileName
        self.noteCount = noteCount
        self.lowestPitch = lowestPitch
        self.highestPitch = highestPitch
        self.durationSeconds = durationSeconds
    }

    /// Whether the song fits on a keyboard of this size (requirement HW-3).
    public func fits(_ range: KeyboardRange) -> Bool {
        range.canPlay(lowest: Pitch(midiNumber: lowestPitch), highest: Pitch(midiNumber: highestPitch))
    }
}

/// The outcome of one practice run, kept per song so progress can be shown later.
public struct RunResult: Codable, Hashable, Sendable {
    public let date: Date
    /// Playback speed as a fraction of the song's tempo.
    public let rate: Double
    /// Hands the player played: "left", "right".
    public let hands: [String]
    public let usedWaitMode: Bool
    /// True when the run reached the end of the song.
    public let completed: Bool
    public let correct: Int
    public let early: Int
    public let late: Int
    public let missed: Int
    public let wrongKeys: Int
    /// Share of the player's notes that were played, 0...1. Missing in runs saved before
    /// the review existed.
    public let accuracy: Double?
    /// Average signed timing offset in seconds; negative is early.
    public let averageOffset: Double?

    public init(
        date: Date, rate: Double, hands: [String], usedWaitMode: Bool, completed: Bool,
        correct: Int, early: Int, late: Int, missed: Int, wrongKeys: Int,
        accuracy: Double? = nil, averageOffset: Double? = nil
    ) {
        self.accuracy = accuracy
        self.averageOffset = averageOffset
        self.date = date
        self.rate = rate
        self.hands = hands
        self.usedWaitMode = usedWaitMode
        self.completed = completed
        self.correct = correct
        self.early = early
        self.late = late
        self.missed = missed
        self.wrongKeys = wrongKeys
    }
}

/// A song opened for practice.
public struct LoadedSong: Sendable {
    public let entry: SongEntry
    public let song: Song
    /// Engraved pages. For MIDI imports this is a draft generated from the notes; it is empty
    /// only if that draft could not be engraved.
    public let pages: [ScoreScene]

    public init(entry: SongEntry, song: Song, pages: [ScoreScene]) {
        self.entry = entry
        self.song = song
        self.pages = pages
    }

    /// Wraps a generated song, such as a drill, engraving a sheet for it.
    /// - Parameters:
    ///   - id: stable identifier, so the song's practice history can be found again.
    ///   - fifths: key signature for the sheet.
    ///   - sharpened: pitch class to spell as a sharp regardless of the key (see `MusicXMLWriter`).
    public init(generated song: Song, id: UUID, fifths: Int = 0, sharpened: Int? = nil) {
        let span = song.pitchSpan
        entry = SongEntry(
            id: id, title: song.title, addedAt: Date(timeIntervalSince1970: 0), format: .drill, fileName: "",
            noteCount: song.notes.count,
            lowestPitch: span?.lowerBound.midiNumber ?? 60, highestPitch: span?.upperBound.midiNumber ?? 60,
            durationSeconds: song.tempoMap.seconds(atBeat: song.length)
        )
        let draft = Data(MusicXMLWriter.draft(from: song, fifths: fifths, sharpened: sharpened).utf8)
        if let score = try? EngravedScore(musicXML: draft, title: song.title) {
            self.song = song.adoptingNotation(of: score.song)
            pages = score.pages
        } else {
            self.song = song
            pages = []
        }
    }
}

/// Keeps imported songs as plain files, one folder per song (requirement PL-3):
/// the original file plus `entry.json`.
public struct SongStore: Sendable {
    public enum StoreError: Error, Equatable {
        case unsupportedFile
        /// The file could not be read as music; the text says why.
        case unreadable(String)
    }

    public let root: URL

    public init(root: URL) {
        self.root = root
    }

    /// `~/Library/Application Support/Midiot/Songs`
    public static var standard: SongStore {
        let support = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
        return SongStore(root: support.appendingPathComponent("Midiot/Songs", isDirectory: true))
    }

    public static let supportedExtensions = ["mid", "midi", "musicxml", "mxl", "xml"]

    /// All songs, newest first. Folders that cannot be read are skipped.
    public func entries() -> [SongEntry] {
        let folders = (try? FileManager.default.contentsOfDirectory(at: root, includingPropertiesForKeys: nil)) ?? []
        return folders
            .compactMap { try? Data(contentsOf: $0.appendingPathComponent("entry.json")) }
            .compactMap { try? Self.decoder.decode(SongEntry.self, from: $0) }
            .sorted { $0.addedAt > $1.addedAt }
    }

    /// Copies a MIDI or MusicXML file into the library after checking that it can be read.
    @discardableResult
    public func importFile(at url: URL) throws -> SongEntry {
        let format: SongEntry.Format
        switch url.pathExtension.lowercased() {
        case "mid", "midi": format = .midi
        case "musicxml", "mxl", "xml": format = .musicXML
        default: throw StoreError.unsupportedFile
        }

        let data = try Data(contentsOf: url)
        let title = url.deletingPathExtension().lastPathComponent
            .replacingOccurrences(of: "_", with: " ")
            .trimmingCharacters(in: .whitespaces)
        let song = try Self.parse(data, format: format, title: title).song
        guard let span = song.pitchSpan else { throw StoreError.unreadable("The file has no notes.") }

        let entry = SongEntry(
            id: UUID(), title: title,
            // Whole seconds, so the value survives being written to and read from disk unchanged.
            addedAt: Date(timeIntervalSince1970: Date().timeIntervalSince1970.rounded(.down)),
            format: format, fileName: url.lastPathComponent,
            noteCount: song.notes.count,
            lowestPitch: span.lowerBound.midiNumber, highestPitch: span.upperBound.midiNumber,
            durationSeconds: song.tempoMap.seconds(atBeat: song.length)
        )
        let folder = folder(for: entry)
        try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        try data.write(to: folder.appendingPathComponent(entry.fileName))
        try Self.encoder.encode(entry).write(to: folder.appendingPathComponent("entry.json"))
        return entry
    }

    public func load(_ entry: SongEntry) throws -> LoadedSong {
        let data = try Data(contentsOf: folder(for: entry).appendingPathComponent(entry.fileName))
        let parsed = try Self.parse(data, format: entry.format, title: entry.title)
        return LoadedSong(entry: entry, song: parsed.song, pages: parsed.pages)
    }

    /// Adds a run to the song's history (`runs.json` in its folder).
    public func appendRun(_ run: RunResult, for entry: SongEntry) throws {
        let all = runs(for: entry) + [run]
        // Generated songs have no folder until their first run is saved.
        try FileManager.default.createDirectory(at: folder(for: entry), withIntermediateDirectories: true)
        try Self.encoder.encode(all).write(to: folder(for: entry).appendingPathComponent("runs.json"))
    }

    /// The song's practice history, oldest first.
    public func runs(for entry: SongEntry) -> [RunResult] {
        guard let data = try? Data(contentsOf: folder(for: entry).appendingPathComponent("runs.json")) else { return [] }
        return (try? Self.decoder.decode([RunResult].self, from: data)) ?? []
    }

    public func delete(_ entry: SongEntry) throws {
        try FileManager.default.removeItem(at: folder(for: entry))
    }

    private func folder(for entry: SongEntry) -> URL {
        root.appendingPathComponent(entry.id.uuidString, isDirectory: true)
    }

    private static func parse(_ data: Data, format: SongEntry.Format, title: String) throws -> (song: Song, pages: [ScoreScene]) {
        switch format {
        case .midi:
            do {
                let song = Song(midiFile: try MIDIFile(data: data), title: title)
                // MIDI carries no notation, so a draft sheet is written and engraved from the notes.
                let draft = Data(MusicXMLWriter.draft(from: song).utf8)
                guard let score = try? EngravedScore(musicXML: draft, title: title) else { return (song, []) }
                return (song.adoptingNotation(of: score.song), score.pages)
            } catch {
                let reason = switch error {
                case .notAMIDIFile: "This is not a MIDI file."
                case .truncated: "The MIDI file is incomplete or damaged."
                case .timecodeBasedTiming: "The MIDI file uses film timecode instead of beats, which is not supported."
                }
                throw StoreError.unreadable(reason)
            }
        case .drill:
            throw StoreError.unsupportedFile
        case .musicXML:
            do {
                let score = try EngravedScore(musicXML: data, title: title)
                return (score.song, score.pages)
            } catch {
                let reason = switch error {
                case .missingResources: "The app's engraving data is missing."
                case .unreadableScore: "The file could not be read as MusicXML."
                case .noNotes: "The score has no notes."
                }
                throw StoreError.unreadable(reason)
            }
        }
    }

    private static let encoder: JSONEncoder = {
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        return encoder
    }()

    private static let decoder: JSONDecoder = {
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        return decoder
    }()
}
